'use strict'

const i18n = require( './i18n.min' )

// Polyfill: make electron-store work in renderer
try {
	const electron = require( 'electron' )
	const remote = require( '@electron/remote' )
	if( !electron.app ) {
		electron.app = remote.app
	}
} catch( e ) {}

const { ipcRenderer } = require( 'electron' )

const Store = require( 'electron-store' )
let store
try {
	store = new Store()
} catch( e ) {
	store = { get: () => null, set: () => {} }
}

const $ = require( 'jquery' )
const jqueryI18next = require( 'jquery-i18next' )
const defaultProfile = require( './ai-default-profile.min' )
const aiClient = require( './ai-client.min' )

jqueryI18next.init(i18n, $)

//note(dgmid): make sure the built-in Default profile is always present

defaultProfile.ensureDefaultProfile( store )



//note(dgmid): log exceptions

window.onerror = function( error, url, line ) {
	
	ipcRenderer.send( 'error-in-render', {error, url, line} )
}



//note(dgmid): set lang & localize strings

$('html').attr('lang', i18n.language)
$('header').localize()
$('label').localize()
$('input').localize()
$('select').localize()
$('button').localize()
$('.hint').localize()



//note(dgmid): helper to show status in the status box

function showStatus( type, html ) {
	
	let $box = $('#test-status')
	
	$box.removeClass('success error pending show').addClass(type + ' show').html( html )
}



//note(dgmid): per-provider field labels / hints / placeholders

const FIELD_TXT = {
	gemini: {
		keyLabel: 'Gemini API Key',
		keyHint: 'Get your free key at ai.google.dev',
		keyPh: 'AIzaSy...',
		keyRequired: true,
		modelLabel: 'Gemini Model',
		modelHint: 'Flash / Lite models are free-tier eligible. Press Test Connection to load the live list.'
	},
	openrouter: {
		keyLabel: 'OpenRouter API Key',
		keyHint: 'Get your key at openrouter.ai/keys. Free models show a Free badge in the list; paid models are billed per token.',
		keyPh: 'sk-or-v1-...',
		keyRequired: true,
		modelLabel: 'OpenRouter Model',
		modelHint: 'Free models have daily request limits. Press Test Connection to load the live list with Free / Paid badges.'
	},
	local: {
		keyLabel: 'API Key (optional)',
		keyHint: 'Only needed if the server requires authentication — leave empty for open servers such as Ollama.',
		keyPh: '',
		keyRequired: false,
		modelLabel: 'Model name',
		modelHint: 'The model the server serves (e.g. glm-4.5, or a Groq model like llama-3.3-70b-versatile). Press Test Connection to fetch the list from the server, or type it.'
	}
}



//note(dgmid): show / hide rows and adapt labels when the provider changes

function applyFieldState() {
	
	let provider = $('#provider').val(),
		txt = FIELD_TXT[ provider ] || FIELD_TXT.gemini
	
	//note(dgmid): base URL row is local-server only
	$('#row-base-url').toggleClass( 'hidden', provider !== 'local' )
	
	//note(dgmid): API key row
	let $key = $('#api-key')
	
	$('#api-key-label').text( txt.keyLabel )
	$('#api-key-hint').text( txt.keyHint )
	$key.attr( 'placeholder', txt.keyPh )
	
	if( txt.keyRequired ) {
		$key.attr( 'required', 'required' )
	} else {
		$key.removeAttr( 'required' )
	}
	
	//note(dgmid): model row — dropdown for Gemini/OpenRouter, text input for local
	let isLocal = ( provider === 'local' )
	
	$('#model-label').text( txt.modelLabel )
	$('#model-hint').text( txt.modelHint )
	$('#model').toggleClass( 'hidden', isLocal )
	$('#model-local').toggleClass( 'hidden', !isLocal )
	
	$('#base-url').attr( 'placeholder', aiClient.PROVIDER_DEFAULTS.local.baseUrl )
}



//note(dgmid): enable/disable the model picker. A missing or failing connection must
//not allow selecting a model — the dropdown gets locked (and replaced by a placeholder
//on failure) until the connection works again.

function setModelControlEnabled( enabled ) {
	
	$('#model').prop('disabled', !enabled)
	$('#model-local').prop('disabled', !enabled)
}



//note(dgmid): auto-test the connection as soon as the key (or the local server URL) is
//typed — a working connection refreshes the model list on the fly; a failed one locks
//the model picker until it works again.

let autoTestTimer = null

function scheduleAutoTest() {
	
	clearTimeout( autoTestTimer )
	
	autoTestTimer = setTimeout( () => {
		
		let provider = $('#provider').val()
		
		if( provider === 'local' ) {
			
			if( !$('#base-url').val().trim() ) {
				
				setModelControlEnabled( false )
				return
			}
			
		} else if( !$('#api-key').val().trim() ) {
			
			setModelControlEnabled( false )
			return
		}
		
		refreshModels( false )
	}, 700 )
}

$('#api-key').on('input change', scheduleAutoTest)
$('#base-url').on('input change', scheduleAutoTest)



//note(dgmid): Gemini model options — humanized labels + free-tier hint, newest first

function renderGeminiModels( models, selectedModel ) {
	
	let $select = $('#model')
	
	$select.empty()
	
	if( !models || models.length === 0 ) {
		
		$select.append( $('<option>', {
			value: '',
			text: i18n.t('aiconfig:status.nomodels', 'No models available'),
			disabled: true,
			selected: true
		}))
		return
	}
	
	let foundSaved = false
	
	models.forEach( m => {
		
		let label = m.id
			.replace( /-/g, ' ' )
			.replace( /\b\w/g, c => c.toUpperCase() )
		
		if( m.free ) {
			label += ( m.id.includes('lite') ? ' (free tier eligible, fastest)' : ' (free tier eligible)' )
		} else {
			label += ' (billed only)'
		}
		
		let $option = $('<option>', {
			value: m.id,
			text: label
		})
		
		if( m.id === selectedModel ) {
			$option.prop('selected', true)
			foundSaved = true
		}
		
		$select.append( $option )
	})
	
	//note(dgmid): if the saved model is no longer in the API list (retired), show it
	//disabled for reference and auto-select a live free-tier model — saving must never
	//keep a dead model. Stable aliases are exempt (they always resolve server-side).
	if( selectedModel && !foundSaved && ![ 'gemini-flash-latest', 'gemini-pro-latest' ].includes( selectedModel ) ) {
		
		$select.prepend( $('<option>', {
			value: selectedModel,
			text: selectedModel + ' (no longer in API list)',
			disabled: true
		}))
		
		let replacement = models.find( m => m.id === 'gemini-3.5-flash-lite' )
		
		if( !replacement ) replacement = models.find( m => m.free )
		
		if( replacement ) $select.val( replacement.id )
	}
}



//note(dgmid): OpenRouter options grouped Free / Paid, straight from the provider's
//pricing data — the free badges the config screen never had for Gemini are real here

function renderOpenRouterModels( models, selectedModel ) {
	
	let $select = $('#model')
	
	$select.empty()
	
	let free = models.filter( m => m.free ),
		paid = models.filter( m => !m.free )
	
	function addGroup( label, list ) {
		
		if( list.length === 0 ) return
		
		let $group = $('<optgroup>', { label: label })
		
		for( let m of list ) {
			$group.append( $('<option>', {
				value: m.id,
				text: m.id + ' — Free',
				selected: ( m.id === selectedModel )
			}))
		}
		
		$select.append( $group )
	}
	
	function addPaidGroup( label, list ) {
		
		if( list.length === 0 ) return
		
		let $group = $('<optgroup>', { label: label })
		
		for( let m of list ) {
			$group.append( $('<option>', {
				value: m.id,
				text: m.id,
				selected: ( m.id === selectedModel )
			}))
		}
		
		$select.append( $group )
	}
	
	addGroup( 'Free models (daily request limit)', free )
	addPaidGroup( 'Paid models (billed per token)', paid )
	
	//note(dgmid): saved model not in the list? keep it visible (disabled) and select
	//the first free model as the live default
	if( selectedModel && !models.some( m => m.id === selectedModel ) ) {
		
		$select.prepend( $('<option>', {
			value: selectedModel,
			text: selectedModel + ' (not in current list)',
			disabled: true
		}))
	}
	
	if( !$select.val() && free.length > 0 ) {
		
		$select.val( free[0].id )
	}
	
	if( !$select.val() ) {
		
		$select.prepend( $('<option>', {
			value: '',
			text: i18n.t('aiconfig:status.nomodels', 'No models available — check your key'),
			disabled: true,
			selected: true
		}))
	}
}



//note(dgmid): static Gemini options used before the live list arrives (and when no key
//is saved yet) — keeps the dropdown honest instead of showing another provider's models

const GEMINI_DEFAULTS = [
	['gemini-3.5-flash', 'Gemini 3.5 Flash (recommended, free tier)'],
	['gemini-3.1-flash-lite', 'Gemini 3.1 Flash-Lite (faster, free tier)'],
	['gemini-2.5-flash', 'Gemini 2.5 Flash (free tier)'],
	['gemini-2.5-pro', 'Gemini 2.5 Pro (billed only)']
]



//note(dgmid): reset the model picker to sensible placeholders when switching providers
//before any live list has loaded (OpenRouter has no static list; Gemini keeps defaults)

function seedModelPicker( provider ) {
	
	let $sel = $('#model')
	
	if( provider === 'openrouter' ) {
		
		let first = $sel.find('option').first()
		
		//note(dgmid): only reseed if the dropdown still holds Gemini defaults or a bare
		//placeholder — an already-loaded OpenRouter list is left alone
		let geminiLeftover = first.length && ( !first.val() || /^gemini-/.test( first.val() ) )
		
		if( geminiLeftover || !first.length ) {
			
			$sel.empty().append( $('<option>', {
				value: '',
				text: '— press Test Connection to load the model list —',
				disabled: true,
				selected: true
			}) )
		}
		
	} else if( provider === 'gemini' ) {
		
		let first = $sel.find('option').first()
		
		let openrouterLeftover = first.length && first.val() === ''
		
		if( openrouterLeftover || !first.length ) {
			
			$sel.empty()
			
			for( let [ id, label ] of GEMINI_DEFAULTS ) {
				$sel.append( $('<option>', { value: id, text: label }) )
			}
		}
	}
}



//note(dgmid): Gemini stable aliases that always resolve to the latest version

function addStableAliases() {
	
	let $select = $('#model')
	
	if( $select.find('option[value="gemini-flash-latest"]').length > 0 ) return
	
	let $group = $('<optgroup>', {
		label: 'Stable aliases (always resolve to latest version)'
	})
	
	$group.append( $('<option>', {
		value: 'gemini-flash-latest',
		text: 'Gemini Flash Latest'
	}))
	
	$group.append( $('<option>', {
		value: 'gemini-pro-latest',
		text: 'Gemini Pro Latest'
	}))
	
	$select.append( $group )
}



//note(dgmid): which model value the user currently has selected/typed, per provider

function currentModelValue( provider ) {
	
	if( provider === 'local' ) return $('#model-local').val().trim()
	
	return $('#model').val() || ''
}



//note(dgmid): set the model control from a saved model value

function setModelValue( provider, model ) {
	
	if( !model ) return
	
	if( provider === 'local' ) {
		
		$('#model-local').val( model )
		
	} else {
		
		$('#model').val( model )
	}
}



//note(dgmid): fetch the model list from the active provider and repopulate the picker.
//auto=true (load / provider switch) suppresses error banners — the list simply stays
//static until the user presses Test Connection.

function refreshModels( auto ) {
	
	let provider = $('#provider').val(),
		cfg = aiClient.normalizeConfig( gatherConfig() )
	
	if( provider === 'gemini' || provider === 'openrouter' ) {
		
		if( !cfg.apiKey ) {
			
			setModelControlEnabled( false )
			
			if( !auto ) showStatus( 'error', i18n.t('aiconfig:status.noapikey', 'Please enter an API key first.') )
			return
		}
		
	} else if( !cfg.baseUrl ) {
		
		setModelControlEnabled( false )
		
		if( !auto ) showStatus( 'error', i18n.t('aiconfig:status.nobaseurl', 'Please enter the local server URL first.') )
		return
	}
	
	if( !auto ) {
		
		$('#test-btn').prop('disabled', true)
		showStatus( 'pending', i18n.t('aiconfig:status.testing', 'Testing connection & fetching models…') )
	}
	
	//note(dgmid): while the connection is being verified, the model picker stays locked —
	//it is re-enabled only when the connection succeeds
	setModelControlEnabled( false )
	
	let savedModel = currentModelValue( provider ) || cfg.model
	
	aiClient.listModels( cfg ).then( models => {
		
		if( provider === 'local' ) {
			
			//note(dgmid): local — fill the datalist so the text input gets suggestions
			let $dl = $('#model-options')
			
			$dl.empty()
			
			for( let m of models ) {
				$dl.append( $('<option>', { value: m.id }) )
			}
			
			if( !$('#model-local').val() && models.length > 0 ) {
				
				$('#model-local').val( models[0].id )
			}
			
			showStatus( 'success', i18n.t('aiconfig:status.success_local', 'Connected to the local server! {{total}} model(s) available.', {
				total: models.length
			}) )
			
		} else {
			
			if( provider === 'gemini' ) {
				
				renderGeminiModels( models, savedModel )
				addStableAliases()
				
				if( [ 'gemini-flash-latest', 'gemini-pro-latest' ].includes( savedModel ) ) {
					
					$('#model').val( savedModel )
				}
				
				let flashCount = models.filter( m => m.free ).length
				
				showStatus( 'success', flashCount > 0
					? i18n.t('aiconfig:status.success_populated', 'Connected! Loaded {{total}} models ({{flash}} free tier eligible).', {
						total: models.length,
						flash: flashCount
					})
					: i18n.t('aiconfig:status.success_basic', 'Connected! API key is valid. Loaded {{total}} models.', {
						total: models.length
					}) )
				
			} else {
				
				renderOpenRouterModels( models, savedModel )
				
				let freeCount = models.filter( m => m.free ).length
				
				showStatus( 'success', i18n.t('aiconfig:status.success_openrouter', 'Connected! Loaded {{total}} models ({{free}} free).', {
					total: models.length,
					free: freeCount
				}) )
			}
		}
		
		//note(dgmid): a successful connection unlocks the model picker
		setModelControlEnabled( true )
		
	}).catch( error => {
		
		setModelControlEnabled( false )
		
		//note(dgmid): a failed connection must not leave a stale, selectable model list —
		//replace the dropdown with a locked placeholder until the connection works again
		if( provider !== 'local' ) {
			
			let $sel = $('#model')
			
			$sel.empty().append( $('<option>', {
				value: '',
				text: i18n.t('aiconfig:status.connectionfailed', 'Connection failed — fix the key/server, then press Test or type the key again'),
				disabled: true,
				selected: true
			}) )
		}
		
		if( !auto ) {
			
			showStatus( 'error',
				i18n.t('aiconfig:status.error', 'Connection failed: {{error}}', { error: error.message || error } )
			)
		}
		
	}).finally( () => {
		
		$('#test-btn').prop('disabled', false)
	})
}



//note(dgmid): provider change — adapt the form and try to refresh the model list

$('#provider').change( function() {
	
	applyFieldState()
	
	seedModelPicker( $('#provider').val() )
	
	refreshModels( true )
})



//note(dgmid): test connection / refresh model list button

$('#test-btn').click( function() {
	
	refreshModels( false )
})



//note(dgmid): gather the current form values into a raw config object

function gatherConfig() {
	
	let provider = $('#provider').val()
	
	return {
		provider: provider,
		apiKey: $('#api-key').val(),
		model: currentModelValue( provider ),
		baseUrl: $('#base-url').val()
	}
}



//note(dgmid): save config

$('#modal-form').submit( function( e ) {
	
	e.preventDefault()
	
	let provider = $('#provider').val(),
		raw = gatherConfig()
	
	let cfg = aiClient.normalizeConfig( raw )
	
	//note(dgmid): client-side validation before persisting
	if( provider === 'gemini' || provider === 'openrouter' ) {
		
		if( !cfg.apiKey ) {
			
			showStatus( 'error', i18n.t( 'aiconfig:error.noapikey', FIELD_TXT[ provider ].keyLabel + ' is required.' ) )
			return
		}
		
	} else if( !cfg.baseUrl ) {
		
		showStatus( 'error', i18n.t('aiconfig:error.nobaseurl', 'The server URL is required.') )
		return
	}
	
	if( !cfg.model ) {
		
		showStatus( 'error', provider === 'local'
			? i18n.t('aiconfig:error.nomodel_local', 'Enter the model name served by the OpenAI-compatible server (or press Test Connection to fetch it).')
			: i18n.t('aiconfig:error.nomodel', 'Choose a model (press Test Connection to load the list).') )
		return
	}
	
	let config = {
		provider: provider,
		apiKey: cfg.apiKey,
		model: cfg.model,
		baseUrl: cfg.baseUrl,
		maxTags: parseInt( $('#max-tags').val() ) || 8,
		maxPerSession: parseInt( $('#max-per-session').val() ) || 100,
		apiGapMs: parseInt( $('#api-gap').val() ) || 0
	}
	
	store.set( 'aiConfig', config )
	
	ipcRenderer.send( 'close-current-window' )
})



//note(dgmid): learned profiles list — per-profile delete and full reset.
//The built-in Default profile is always present, shown with a badge, and
//cannot be deleted; reset re-seeds it instead of emptying the list.

function renderProfiles() {
	
	let profiles = defaultProfile.ensureDefaultProfile( store )
	
	let $list = $('#profiles-list')
	$list.empty()
	
	let learned = profiles.filter( p => !defaultProfile.isBuiltin( p ) )
	
	$('#btn-reset-profiles').prop('disabled', learned.length === 0)
	
	for( let p of profiles ) {
		
		let builtin = defaultProfile.isBuiltin( p )
		
		let $row = $('<div>', {
			style: 'display:flex;align-items:flex-start;gap:8px;padding:6px 8px;border:1px solid var(--tab-dividers);border-radius:4px;margin-bottom:6px;background:var(--stripe-even);'
		})
		
		$row.append( $('<div>', { style: 'flex:1 1 auto;min-width:0;' })
			.append( $('<div>', { style: 'font-weight:600;font-size:12px;word-wrap:break-word;', html: builtin
				? i18n.t('aiconfig:label.defaultprofile', 'Default (built-in)') + ' <span style="font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.03em;background:var(--accent);color:#fff;padding:1px 5px;border-radius:3px;vertical-align:middle;">' + i18n.t('aiconfig:label.builtin', 'Built-in') + '</span>'
				: p.name }) )
			.append( $('<div>', { style: 'font-size:11px;opacity:.7;word-wrap:break-word;', text: p.description || '' }) )
			.append( $('<div>', { style: 'font-size:10px;opacity:.5;margin-top:2px;', text: builtin
				? i18n.t('aiconfig:label.default_source', 'Ships with the app — cannot be deleted')
				: i18n.t('aiconfig:label.profile_source', 'Learned from: {{folder}}', { folder: p.sourceFolder || 'Home' }) }) )
		)
		
		if( !builtin ) {
			
			let $del = $('<button>', {
				type: 'button',
				class: 'ui-button',
				style: 'font-size:11px;padding:3px 10px;flex:none;',
				text: i18n.t('aiconfig:button.deleteprofile', 'Delete')
			})
			
			$del.click( function() {
				
				let response = ipcRenderer.sendSync('show-message-box', {
					message: i18n.t('aiconfig:dialog.deleteprofile', 'Delete the profile "{{name}}"?', { name: p.name }),
					detail: i18n.t('aiconfig:dialog.deleteprofile_detail', 'This profile will no longer be offered in Auto-Organize.'),
					buttons: [ i18n.t('aiconfig:button.deleteprofile', 'Delete'), i18n.t('aiconfig:dialog.cancel', 'Cancel') ]
				})
				
				if( response === 0 ) {
					
					let remaining = ( store.get( 'aiProfiles' ) || [] ).filter( x => !defaultProfile.isBuiltin( x ) && String( x.id ) !== String( p.id ) )
					store.set( 'aiProfiles', remaining )
					renderProfiles()
				}
			})
			
			$row.append( $del )
		}
		
		$list.append( $row )
	}
}

$('#btn-reset-profiles').click( function() {
	
	let learned = ( store.get( 'aiProfiles' ) || [] ).filter( p => !defaultProfile.isBuiltin( p ) )
	
	if( learned.length === 0 ) return
	
	let response = ipcRenderer.sendSync('show-message-box', {
		message: i18n.t('aiconfig:dialog.resetprofiles', 'Reset all learned profiles?'),
		detail: i18n.t('aiconfig:dialog.resetprofiles_detail', 'This clears every learned profile. The built-in Default profile always stays.'),
		buttons: [ i18n.t('aiconfig:button.resetprofiles', 'Reset Learning'), i18n.t('aiconfig:dialog.cancel', 'Cancel') ]
	})
	
	if( response === 0 ) {
		
		store.set( 'aiProfiles', [ defaultProfile.getDefaultProfile() ] )
		renderProfiles()
	}
})



//note(dgmid): cancel button

$('#cancel').click( function() {
	
	ipcRenderer.send( 'close-current-window' )
})



//note(dgmid): load the saved config (provider-aware, backward compatible: old configs
//have no provider field → Gemini) and auto-refresh the live model list on open

let savedConfig = store.get( 'aiConfig' )

if( savedConfig ) {
	
	let provider = savedConfig.provider || 'gemini'
	
	if( aiClient.PROVIDERS.includes( provider ) ) {
		
		$('#provider').val( provider )
	}
	
	if( savedConfig.apiKey )	$('#api-key').val( savedConfig.apiKey )
	if( savedConfig.baseUrl )	$('#base-url').val( savedConfig.baseUrl )
	
	applyFieldState()
	
	seedModelPicker( provider )
	
	if( provider === 'local' ) {
		
		$('#model-local').val( savedConfig.model || '' )
		
	} else if( savedConfig.model ) {
		
		$('#model').val( savedConfig.model )
	}
	
	if( savedConfig.maxTags )		$('#max-tags').val( savedConfig.maxTags )
	if( savedConfig.maxPerSession )	$('#max-per-session').val( savedConfig.maxPerSession )
	if( savedConfig.apiGapMs != null )	$('#api-gap').val( savedConfig.apiGapMs )
	
	//note(dgmid): auto-refresh the model list when a key (or a local server URL) is
	//already saved, so the dropdown always reflects what the provider currently offers
	setTimeout( () => {
		
		refreshModels( true )
	}, 50 )
	
} else {
	
	applyFieldState()
	
	seedModelPicker( $('#provider').val() )
}

renderProfiles()
